-- MySQL8 after V011. No default policy, threshold, required status or enrollment mapping is inferred.
SET @lc_eval_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE exams ADD COLUMN version BIGINT NOT NULL DEFAULT 0','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='exams' AND column_name='version');
PREPARE lc_eval_stmt FROM @lc_eval_sql;EXECUTE lc_eval_stmt;DEALLOCATE PREPARE lc_eval_stmt;
SET @lc_eval_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE exam_candidates ADD COLUMN enrollment_id BIGINT NULL','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='exam_candidates' AND column_name='enrollment_id');
PREPARE lc_eval_stmt FROM @lc_eval_sql;EXECUTE lc_eval_stmt;DEALLOCATE PREPARE lc_eval_stmt;
CREATE TABLE IF NOT EXISTS evaluation_states(class_id BIGINT NOT NULL PRIMARY KEY,branch_id BIGINT NOT NULL,revision BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS evaluation_policies(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,class_id BIGINT NOT NULL,branch_id BIGINT NOT NULL,course_id BIGINT NOT NULL,revision BIGINT NOT NULL,pass_percent DECIMAL(5,2) NOT NULL,min_attendance_percent DECIMAL(5,2) NULL,actor_id BIGINT NOT NULL,actor_name VARCHAR(255) NOT NULL,confirmed_at DATETIME(6) NOT NULL,reason VARCHAR(500) NOT NULL,CONSTRAINT uk_evaluation_policy_revision UNIQUE(class_id,revision));
CREATE TABLE IF NOT EXISTS evaluation_policy_exams(policy_id BIGINT NOT NULL,exam_id BIGINT NOT NULL,exam_version BIGINT NOT NULL,exam_name VARCHAR(255) NOT NULL,exam_date DATE NOT NULL,required BIT NOT NULL,weight DECIMAL(7,2) NOT NULL,max_score DECIMAL(7,2) NOT NULL,CONSTRAINT uk_evaluation_policy_exam UNIQUE(policy_id,exam_id),CONSTRAINT fk_evaluation_policy FOREIGN KEY(policy_id) REFERENCES evaluation_policies(id),CONSTRAINT fk_evaluation_exam FOREIGN KEY(exam_id) REFERENCES exams(id));
